def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'

    # Extract sequences
    my = [h[0] for h in history]
    op = [h[1] for h in history]

    opp_c = op.count('C')
    opp_d = n - opp_c
    my_c = my.count('C')
    my_d = n - my_c

    last_my = my[-1]
    last_op = op[-1]

    # If opponent has never defected, keep cooperating almost always
    if opp_d == 0:
        # Very rare probe to check if they still cooperate after defection
        if n >= 4 and n % 23 == 0 and my_d < 2:
            return 'D'
        return 'C'

    # Aggressive response to sustained defection
    if opp_d >= n * 0.85:
        # Almost pure defect, but rare cooperation to reset deadlock
        if rng.random() < 0.03:
            return 'C'
        return 'D'

    # Detect long defection streak by opponent
    opp_def_streak = 0
    for i in range(n - 1, -1, -1):
        if op[i] == 'D':
            opp_def_streak += 1
        else:
            break

    # Detect long cooperation streak by opponent
    opp_c_streak = 0
    for i in range(n - 1, -1, -1):
        if op[i] == 'C':
            opp_c_streak += 1
        else:
            break

    # If opponent is in long cooperation streak, cooperate
    if opp_c_streak >= 2:
        # Late-game exploit if opponent is very cooperative
        if n >= 92 and opp_c > n * 0.85:
            if rng.random() < 0.12:
                return 'D'
        return 'C'

    # Opponent just defected
    if last_op == 'D':
        # If they defected while we cooperated, retaliate
        if last_my == 'C':
            # But if they defected just once among mostly cooperation, forgive sometimes
            if opp_d <= 2 and n >= 6:
                if rng.random() < 0.35:
                    return 'C'
            return 'D'
        # Both defected - check if we're in DD loop
        if last_my == 'D':
            # If opponent has mostly cooperated overall, try to restore
            if opp_d <= n * 0.25:
                if rng.random() < 0.55:
                    return 'C'
            # If opponent has been defecting a lot, keep defecting
            if opp_def_streak >= 4:
                return 'D'
            # Otherwise, try cooperation to break cycle sometimes
            if rng.random() < 0.3:
                return 'C'
            return 'D'

    # Opponent cooperated last (last_op == 'C')
    if last_op == 'C':
        # If we defected and opponent cooperated, they're forgiving - exploit moderately
        if last_my == 'D':
            # Count how often opponent cooperated after our defections
            forgive_count = 0
            our_def_count = 0
            for i in range(1, n):
                if my[i - 1] == 'D':
                    our_def_count += 1
                    if op[i] == 'C':
                        forgive_count += 1
            if our_def_count > 0 and forgive_count >= our_def_count * 0.6:
                # Opponent is very forgiving - exploit more
                if rng.random() < 0.5:
                    return 'D'
            return 'C'
        # Both cooperated - continue cooperating, rare probe
        if n >= 6 and opp_c >= 5 and rng.random() < 0.04:
            return 'D'
        return 'C'

    # Default fallback
    return 'C'
